47	function runStepPilot(
48	  cmd: string,
49	  args: string[],
50	  cwd: string,
51	  timeoutMs: number,
52	): { stdout: string; stderr: string; exitCode: number | null } {
53	  return new Promise((resolve) => {
54	    let stdout = '';
55	    let stderr = '';
56	    let settled = false;
57	
58	    const finish = (err?: any) => {
59	      if (settled) return;
60	      settled = true;
61	      clearTimeout(timer);
62	      resolve({
63	        stdout,
64	        stderr,
65	        exitCode: err?.status ?? null,
66	      });
67	    };
68	
69	    const timer = setTimeout(() => finish(new Error('timeout')), timeoutMs);
70	
71	    // Windows cannot execute `.js` files directly via spawn without shell;
72	    // route them through `node` explicitly so we can capture stream-json output.
73	    const useShell = !cmd.endsWith('.js');
74	    const proc = useShell
75	      ? spawn(cmd, args, { cwd, stdio: ['pipe', 'pipe', 'pipe'], shell: true })
76	      : spawn('node', [cmd, ...args], { cwd, stdio: ['pipe', 'pipe', 'pipe'], shell: false });
77	
78	    proc.stdout.on('data', (data) => {
79	      stdout += data.toString();
80	    });
81	    proc.stderr.on('data', (data) => {
82	      stderr += data.toString();
83	    });
84	    proc.on('error', finish);
85	    proc.on('close', finish);
86	  });
87	}
