183	function captureMetrics(
184	  ev: RawEvent,
185	  setters: {
186	    toolCalls: (v: number) => void;
187	    toolErrors: (v: number) => void;
188	    retries: (v: number) => void;
189	    compactions: (v: number) => void;
190	    inputTokens: (v: number) => void;
191	    outputTokens: (v: number) => void;
192	    totalTokens: (v: number) => void;
193	    stopReason: (v: string | null) => void;
194	    failureReason: (v: string | null) => void;
195	    turns: (v: number) => void;
196	    resultSubtype: (v: string | null) => void;
197	  },
198	) {
199	  switch (ev.type) {
200	    case 'thinking_start':
201	      setters.turns((v) => v + 1);
202	      break;
203	    case 'tool_start':
204	      setters.toolCalls((v) => v + 1);
205	      break;
206	    case 'tool_end': {
207	      const end = ev as { isError?: boolean };
208	      if (end.isError) setters.toolErrors((v) => v + 1);
209	      break;
210	    }
211	    case 'retry':
212	      setters.retries((v) => v + 1);
213	      break;
214	    case 'context.apply_compaction':
215	      setters.compactions((v) => v + 1);
216	      break;
217	    case 'usage': {
218	      const u = ev as { totalTokens?: number; billedDelta?: number };
219	      if (typeof u.totalTokens === 'number') setters.totalTokens(u.totalTokens);
220	      if (typeof u.billedDelta === 'number') setters.outputTokens((v) => v + u.billedDelta!);
221	      break;
222	    }
223	    case 'model.usage': {
224	      const mu = ev as {
225	        totalTokens?: number;
226	        inputTokens?: number;
227	        outputTokens?: number;
228	        cacheReadTokens?: number;
229	        cacheCreationTokens?: number;
230	      };
231	      if (typeof mu.totalTokens === 'number') setters.totalTokens(mu.totalTokens);
232	      if (typeof mu.inputTokens === 'number') setters.inputTokens(mu.inputTokens);
233	      if (typeof mu.outputTokens === 'number') setters.outputTokens(mu.outputTokens);
234	      break;
235	    }
236	    case 'result':
237	      setters.resultSubtype((ev as { subtype?: string }).subtype ?? null);
238	      break;
239	    case 'error':
240	      setters.failureReason((ev as { message?: string }).message ?? 'error');
241	      setters.resultSubtype('error');
242	      break;
243	    case 'turn.issue': {
244	      const issue = ev as { kind?: string; message?: string };
245	      if (issue.kind === 'empty' || issue.kind === 'error') {
246	        setters.failureReason(issue.message ?? issue.kind ?? 'turn.issue');
247	      }
248	      break;
249	    }
250	    default:
251	      break;
252	  }
253	}
