283	async function executeCheck(check: { type: string; command?: string; path?: string; pattern?: string; expect?: Record<string, unknown> }, repoDir: string): Promise<boolean> {
284	  switch (check.type) {
285	    case 'test': {
286	      try {
287	        const { execSync } = await import('node:child_process');
288	        const output = execSync(check.command ?? '', {
289	          cwd: repoDir,
290	          encoding: 'utf8',
291	          stdio: 'pipe',
292	        });
293	        if (check.expect?.exit_code !== undefined && check.expect.exit_code !== 0) {
294	          return false;
295	        }
296	        if (check.expect?.stdout_contains && !output.includes(check.expect.stdout_contains as string)) {
297	          return false;
298	        }
299	        if (check.expect?.stderr_not_contains && output.toLowerCase().includes((check.expect.stderr_not_contains as string).toLowerCase())) {
300	          return false;
301	        }
302	        return true;
303	      } catch {
304	        return false;
305	      }
306	    }
307	    case 'file_contains': {
308	      const filePath = join(repoDir, check.path ?? '');
309	      if (!existsSync(filePath)) return false;
310	      const content = readFileSync(filePath, 'utf8');
311	      const regex = new RegExp(check.pattern ?? '');
312	      return regex.test(content);
313	    }
314	    case 'file_not_contains': {
315	      const filePath = join(repoDir, check.path ?? '');
316	      if (!existsSync(filePath)) return true;
317	      const content = readFileSync(filePath, 'utf8');
318	      const regex = new RegExp(check.pattern ?? '');
319	      return !regex.test(content);
320	    }
321	    case 'file_exists': {
322	      const filePath = join(repoDir, check.path ?? '');
323	      return existsSync(filePath);
324	    }
325	    case 'command': {
326	      try {
327	        const { execSync } = await import('node:child_process');
328	        const output = execSync(check.command ?? '', {
329	          cwd: repoDir,
330	          encoding: 'utf8',
331	          stdio: 'pipe',
332	        });
333	        if (check.expect?.exit_code !== undefined) {
334	          // Can't easily check exit code here, assume success if no throw
335	        }
336	        if (check.expect?.stdout_contains && !output.includes(check.expect.stdout_contains as string)) {
337	          return false;
338	        }
339	        return true;
340	      } catch {
341	        return false;
342	      }
343	    }
344	    default:
345	      return false;
346	  }
